The `clean/mergeable` and `dirty/behind` branches build near-identical objects (`ticketKey`, `prNumber`, `prUrl`, `mergeState` are copy-pasted). A shared base keeps future field additions single-site:

```javascript
function approvedPrMergeGapAnomaly(key, number, pr, state, hasApproval) {
    if (!hasApproval) return null;
    var base = { ticketKey: key, prNumber: number, prUrl: prUrl(pr), mergeState: state };
    if (state === 'clean' || state === 'mergeable') {
        return Object.assign(base, {
            type: 'approved-pr-not-merged',
            severity: 'blocking',
            safeAction: 'trigger-sm-retry-merge',
            message: 'PR is approved and clean but still open.'
        });
    }
    if (state === 'dirty' || state === 'behind') {
        return Object.assign(base, {
            type: 'approved-pr-not-mergeable',
            severity: 'warning',
            safeAction: state === 'behind' ? 'request-branch-update' : null,
            message: 'PR is approved but not currently mergeable.'
        });
    }
    return null;
}
```

Polish-only: the duplication is carried over faithfully from the pre-extraction inline code, behavior is identical, and the characterization tests already pin both shapes — no need to hold the merge for it (`Object.assign` is already used in production `js/` files, so it is GraalJS/repo-idiomatic)."
